<template><view class="page"><view class="card"><text class="heading">语音农事归档</text><text class="muted">{{farmName}} · 录入后请核对地块、用量和操作时间。</text><textarea v-model="transcript" class="input-area" placeholder="输入或粘贴语音转写文字" :maxlength="12000"/><view class="buttons"><button size="mini" :disabled="busy" @click="record">{{recording?'停止录音':'录制语音'}}</button><text v-if="audioPath" class="muted">录音已就绪</text></view><button class="primary" :loading="busy" :disabled="busy||recording||(!transcript.trim()&&!audioPath)" @click="create">保存归档草稿</button></view><view v-if="error" class="error">{{error}}<button size="mini" @click="load">重试</button></view><view v-for="item in rows" :key="item.id" class="card" @click="open(item)"><text class="heading">{{item.transcript || '语音草稿'}}</text><text class="muted">{{item.state}} · {{item.createdAt}}</text></view><view v-if="detail" class="card"><text class="heading">归档详情</text><view class="buttons"><button v-if="detail.audioAvailable" size="mini" :disabled="busy" @click="playAudio">播放原始录音</button><button v-if="detail.extraction?.suggestion?.draft" size="mini" :disabled="busy" @click="useSuggestion">填入候选待核对</button><button size="mini" :disabled="busy" @click="exportArchive">导出已归档记录</button></view><button v-if="audioSource" size="mini" @click="stopAudio">停止播放</button><business-detail :value="detail"/><view class="buttons"><button size="mini" :disabled="busy" @click="edit">修订内容</button><button v-for="a in actions" :key="a.key" size="mini" :disabled="busy" @click="action=a.key; actionForm={}">{{a.label}}</button></view><view v-if="action"><business-fields :fields="action==='edit'?editFields:actionFields" v-model="actionForm" :farm-id="farmId" :disabled="busy" @ready="ready=$event"/><view v-if="saveError" class="error">{{saveError}}</view><button class="primary" :disabled="busy||!ready" :loading="busy" @click="save">确认保存</button></view></view></view></template>
<script setup lang="ts">
import {ref} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {call,text,number,note,date,reference,plot,yesno} from '@/api/native-business'
import type {Row} from '@/api/native-business'
import {downloadBinary,saveText,contextGuard} from '@/utils/business-files'
import {uploadVoice} from '@/api/native-upload'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import {productionContextVersion} from '@/utils/request'
import BusinessFields from '@/components/business-fields/business-fields.vue'
import BusinessDetail from '@/components/business-detail/business-detail.vue'
let player:ReturnType<typeof uni.createInnerAudioContext>|undefined
function stopAudio(){player?.stop();player?.destroy();player=undefined;audioSource.value=''}
const audioSource=ref('')
const farmId=ref(''),farmName=ref(''),rows=ref<Row[]>([]),detail=ref<Row>(),transcript=ref(''),audioPath=ref(''),recording=ref(false),busy=ref(false),error=ref(''),saveError=ref(''),action=ref(''),actionForm=ref<Row>({}),ready=ref(false)
let scope=0,version=0,recorder:ReturnType<typeof uni.getRecorderManager>|undefined
const actions=[{key:'transcribe',label:'语音转写'},{key:'extract',label:'提取业务字段'},{key:'review',label:'人工复核'},{key:'archive',label:'确认归档'},{key:'void',label:'作废草稿'}]
const actionFields=[note('reason','处理说明',true),yesno('confirmed','已核对所有归档字段'),yesno('abnormalConfirmed','已确认异常提示'),reference('existingUsageId','关联已有用量记录','/inputs/usages','usageId','inputName')]
const editFields=[note('transcript','转写文字',true),plot(),reference('batchId','采收批次','/harvests','batchId','batchNo'),text('operationType','农事类型',true),text('operatedAt','操作时间',true),reference('operatorId','操作人','/members','id','memberName'),number('areaMu','面积（亩）'),reference('inputId','投入品','/inputs','inputId','inputName'),number('quantity','用量'),text('unit','单位'),number('durationHours','工时'),note('description','操作描述'),number('safetyIntervalDays','安全间隔（天）'),number('registeredMaxPerMu','登记亩用量上限'),text('evidenceRef','登记及核验依据'),note('reason','修订原因',true)]
async function load(){const current=++version;error.value='';try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||'';scope=productionContextVersion();const result=await call('/voice-records','GET',undefined,{farmId:farmId.value});if(current===version)rows.value=result}catch(e:any){error.value=e.message}}
async function open(row:Row){stopAudio();if(busy.value)return;error.value='';try{detail.value=await call('/voice-records/'+row.id);action.value=''}catch(e:any){error.value=e.message}}
function edit(){action.value='edit';actionForm.value={...detail.value?.draft,transcript:detail.value?.transcript,reason:''}}
async function create(){if(busy.value)return;busy.value=true;error.value='';try{detail.value=await uploadVoice(farmId.value,transcript.value,audioPath.value||undefined);transcript.value='';audioPath.value='';await load();uni.showToast({title:'草稿已保存',icon:'success'})}catch(e:any){error.value=e.message}finally{busy.value=false}}
function record(){if(busy.value)return;if(!recorder){try{recorder=uni.getRecorderManager();recorder.onStop(result=>{recording.value=false;audioPath.value=result.tempFilePath});recorder.onError((e:any)=>{recording.value=false;error.value=e.errMsg||'录音失败，请检查麦克风权限'})}catch{error.value='当前浏览器不支持录音，可输入转写文字或使用小程序、APP录音';return}}if(recording.value){recorder.stop();return}try{recorder.start({duration:60000,format:'mp3'});recording.value=true}catch{error.value='录音不可用，请检查麦克风权限或输入转写文字'}}
async function save(){if(busy.value||!detail.value)return;saveError.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更');if(!actionForm.value.reason?.trim())throw new Error('请填写处理说明');busy.value=true;const data={...actionForm.value};for(const k of ['operatorId','batchId','inputId','areaMu','quantity','durationHours','safetyIntervalDays','registeredMaxPerMu','existingUsageId']){if(data[k]===''||data[k]===undefined)delete data[k];else{data[k]=Number(data[k]);if(!Number.isFinite(data[k]))throw new Error('数值字段无效')}}if(action.value==='edit'){const {transcript,reason,...draft}=data;detail.value=await call('/voice-records/'+detail.value.id,'PUT',{revision:detail.value.revision,transcript,reason,draft})}else{detail.value=await call('/voice-records/'+detail.value.id+'/'+action.value,'POST',{revision:detail.value.revision,...data})}action.value='';await load()}catch(e:any){saveError.value=e.message}finally{busy.value=false}}
function useSuggestion(){edit();actionForm.value={...actionForm.value,...detail.value?.extraction?.suggestion?.draft,reason:''};saveError.value='候选内容仅供核对，请逐项检查后保存'}
async function playAudio(){if(busy.value||!detail.value)return;busy.value=true;try{stopAudio();audioSource.value=await downloadBinary('/api/v1/production/voice-records/'+encodeURIComponent(detail.value.id)+'/audio');player=uni.createInnerAudioContext();player.src=audioSource.value;player.onError(e=>{error.value=e.errMsg||'播放失败';stopAudio()});player.onEnded(stopAudio);player.play()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function exportArchive(){if(busy.value)return;busy.value=true;try{const guard=contextGuard();const data=await call('/voice-records/export','GET',undefined,{farmId:farmId.value});guard();await saveText('已归档农事.json',JSON.stringify(data,null,2))}catch(e:any){error.value=e.message}finally{busy.value=false}}
onShow(()=>void load());onHide(()=>{version++;stopAudio();if(recording.value)recorder?.stop();action.value='';detail.value=undefined})
</script>
<style scoped>.page{padding:24rpx;background:#f4f6f2}.card{padding:28rpx;background:#fff;border-radius:18rpx;margin-bottom:24rpx}.heading{display:block;font-size:31rpx;font-weight:600;line-height:1.6;word-break:break-word}.muted{display:block;color:#666666;font-size:24rpx;line-height:1.6;margin:16rpx 0}.input-area{box-sizing:border-box;width:100%;height:220rpx;background:#f4f7f0;padding:22rpx;border-radius:12rpx;font-size:28rpx}.buttons{display:flex;flex-wrap:wrap;gap:14rpx;margin-top:20rpx}.buttons button{margin:0;font-size:25rpx;min-height:76rpx;line-height:76rpx}.primary{background:#0f7a45;color:#fff;margin-top:24rpx;font-size:28rpx}.error{padding:22rpx;background:#fff0e8;color:#a43c27;line-height:1.6;margin-bottom:24rpx;font-size:26rpx}</style>
